"""Original vector illustrations for the wedding; no external image requests."""
from pathlib import Path
from math import sin, cos, pi

root = Path(__file__).resolve().parents[1] / 'public'

def leaf_branch(x, y, angle=0, scale=1, color='#718063'):
    leaves = ''.join(f'<ellipse cx="{(-1 if i%2 else 1)*19}" cy="{15+i*20}" rx="9" ry="23" transform="rotate({-38 if i%2 else 38} {(-1 if i%2 else 1)*19} {15+i*20})" fill="{color}" opacity="{.65 + (i%3)*.12}"/>' for i in range(8))
    return f'<g transform="translate({x} {y}) rotate({angle}) scale({scale})"><path d="M0 0 Q-4 90 0 180" stroke="{color}" stroke-width="2" fill="none"/>{leaves}</g>'

def flower(x, y, r, color='#faf7ed', center='#d4bd82'):
    petals=''.join(f'<ellipse cx="{cos(i*pi/5)*r*.45:.1f}" cy="{sin(i*pi/5)*r*.45:.1f}" rx="{r*.55}" ry="{r*.38}" transform="rotate({i*36} {cos(i*pi/5)*r*.45:.1f} {sin(i*pi/5)*r*.45:.1f})" fill="{color}" stroke="#c5bda2" stroke-width=".5"/>' for i in range(10))
    return f'<g transform="translate({x} {y})">{petals}<circle r="{r*.18}" fill="{center}"/>' + ''.join(f'<circle cx="{cos(i)*r*.12:.1f}" cy="{sin(i)*r*.12:.1f}" r="1" fill="#ae975e"/>' for i in range(12)) + '</g>'

